import { apiClient } from './client'
import type { Appointment, CreateAppointmentInput } from '../types/models'
export const appointmentsApi={create:async(p:CreateAppointmentInput)=>(await apiClient.post<{message:string;appointment:Appointment}>('/patient/appointments',p)).data,list:async()=>(await apiClient.get<{appointments:Appointment[]}>('/patient/appointments')).data.appointments,get:async(id:string)=>(await apiClient.get<{appointment:Appointment}>(`/patient/appointments/${id}`)).data.appointment,cancel:async(id:string,cancellationReason?:string)=>(await apiClient.patch<{message:string;appointment:Appointment}>(`/patient/appointments/${id}/cancel`,{cancellationReason})).data}
